using System;
using System.Collections.Generic;
using System.IO;
using System.Threading.Tasks;
using UnityEngine;
using UnityEngine.Rendering;

/// Loads the La Montagne city meshes (buildings, roads, sidewalks, rail, water) generated by Tools/build_city.py
/// from StreamingAssets/LaMontagne/city.bin and builds chunked meshes + mesh colliders at startup.
public class CityLoader : MonoBehaviour
{
    public string[] materialNames;
    public Material[] materials;
    public Material fallback;
    public bool buildColliders = true;
    public static bool Loaded { get; private set; }
    public static float LoadSeconds { get; private set; }
    public static int Triangles { get; private set; }
    public Material waterMaterial;

    void Awake()
    {
        Loaded = false;
        float t0 = Time.realtimeSinceStartup;
        try { Load(); }
        catch (Exception e) { Debug.LogError("[CITY] load failed: " + e); }
        LoadSeconds = Time.realtimeSinceStartup - t0;
        Loaded = true;
        Debug.Log($"[CITY] loaded in {LoadSeconds:F2}s, triangles={Triangles}");
    }

    static T[] ReadArray<T>(BinaryReader br, int count) where T : struct
    {
        int size = System.Runtime.InteropServices.Marshal.SizeOf<T>();
        byte[] b = br.ReadBytes(count * size);
        var arr = new T[count];
        System.Runtime.InteropServices.MemoryMarshal.Cast<byte, T>(b).CopyTo(arr);
        return arr;
    }

    readonly List<Mesh> colMeshes = new List<Mesh>();
    readonly List<GameObject> colObjs = new List<GameObject>();
    readonly Dictionary<string, Transform> parents = new Dictionary<string, Transform>();
    bool deferColliders;

    Dictionary<string, Material> MatMap()
    {
        var map = new Dictionary<string, Material>();
        if (materialNames != null)
            for (int i = 0; i < materialNames.Length && i < materials.Length; i++) map[materialNames[i]] = materials[i];
        return map;
    }

    void Load()
    {
        string path = Path.Combine(Application.streamingAssetsPath, "LaMontagne", "city.bin");
        bool web = Application.platform == RuntimePlatform.WebGLPlayer;
        if (web || !File.Exists(path))
        {
            byte[] data = null;
            var ta = Resources.Load<TextAsset>("LaMontagne/city_web");
            if (ta != null) { data = ta.bytes; Resources.UnloadAsset(ta); }
            else
            {
                // split into parts < 50 MB (git-friendly): city_web_0.bytes, city_web_1.bytes, ...
                var parts = new List<byte[]>(); int total = 0;
                for (int i = 0; ; i++)
                {
                    var tp = Resources.Load<TextAsset>("LaMontagne/city_web_" + i);
                    if (tp == null) break;
                    var pb = tp.bytes; parts.Add(pb); total += pb.Length; Resources.UnloadAsset(tp);
                }
                if (parts.Count > 0)
                {
                    data = new byte[total]; int o = 0;
                    foreach (var pb in parts) { Buffer.BlockCopy(pb, 0, data, o, pb.Length); o += pb.Length; }
                }
            }
            if (data != null) { deferColliders = web; LoadWeb(data); FinishColliders(); return; }
        }
        var map = MatMap();
        using var br = new BinaryReader(File.OpenRead(path));
        string magic = new string(br.ReadChars(4));
        if (magic != "LMC2") throw new Exception("bad magic " + magic);
        int nm = br.ReadInt32();
        var mats = new Material[nm];
        for (int i = 0; i < nm; i++)
        {
            string n = System.Text.Encoding.UTF8.GetString(br.ReadBytes(br.ReadInt32()));
            mats[i] = map.TryGetValue(n, out var m) && m ? m : fallback;
            if (n == "Water") waterMaterial = mats[i];
        }
        int nc = br.ReadInt32();
        for (int c = 0; c < nc; c++)
        {
            string name = System.Text.Encoding.UTF8.GetString(br.ReadBytes(br.ReadInt32()));
            int nv = br.ReadInt32();
            var pos = ReadArray<Vector3>(br, nv);
            var nrm = ReadArray<Vector3>(br, nv);
            var uv = ReadArray<Vector2>(br, nv);
            int ns = br.ReadInt32();
            var mesh = new Mesh { name = name, indexFormat = nv > 65000 ? IndexFormat.UInt32 : IndexFormat.UInt16 };
            mesh.SetVertices(pos); mesh.SetNormals(nrm); mesh.SetUVs(0, uv);
            mesh.subMeshCount = ns;
            var rm = new Material[ns];
            for (int s = 0; s < ns; s++)
            {
                int mid = br.ReadInt32(); int ni = br.ReadInt32();
                var idx = ReadArray<int>(br, ni);
                mesh.SetTriangles(idx, s, false);
                rm[s] = mats[mid];
                Triangles += ni / 3;
            }
            AddChunk(name, mesh, rm, true);
        }
        FinishColliders();
    }

    void AddChunk(string name, Mesh mesh, Material[] rm, bool tangents)
    {
        mesh.RecalculateBounds();
        string layer = name.Substring(0, name.IndexOf('_'));
        if (tangents) mesh.RecalculateTangents();
        if (!parents.TryGetValue(layer, out var par))
        {
            par = new GameObject("City_" + layer).transform; par.SetParent(transform, false); parents[layer] = par;
        }
        var go = new GameObject(name);
        go.transform.SetParent(par, false);
        go.isStatic = true;
        go.AddComponent<MeshFilter>().sharedMesh = mesh;
        var mr = go.AddComponent<MeshRenderer>();
        mr.sharedMaterials = rm;
        bool caster = layer == "bld" || ((layer == "furn" || layer == "bar" || layer == "car") && !Application.isMobilePlatform);
        mr.shadowCastingMode = caster ? ShadowCastingMode.On : ShadowCastingMode.Off;
        if (layer == "water") mr.receiveShadows = true;
        bool col = buildColliders && layer != "water" && layer != "mark";
        if (col) { colMeshes.Add(mesh); colObjs.Add(go); }
        else if (Application.platform == RuntimePlatform.WebGLPlayer) mesh.UploadMeshData(true);   // free the CPU copy
    }

    void FinishColliders()
    {
        if (!buildColliders) return;
        if (!deferColliders)
        {
            var ids = new int[colMeshes.Count];
            for (int i = 0; i < ids.Length; i++) ids[i] = colMeshes[i].GetInstanceID();
            Parallel.For(0, ids.Length, i => Physics.BakeMesh(ids[i], false));
            for (int i = 0; i < ids.Length; i++) colObjs[i].AddComponent<MeshCollider>().sharedMesh = colMeshes[i];
            colMeshes.Clear(); colObjs.Clear();
            return;
        }
        // WebGL (single thread): bake the colliders around the player now, the rest progressively (nearest first)
        Vector3 p = Vector3.zero; var pl = FindAnyObjectByType<FPSController>(); if (pl) p = pl.transform.position;
        var order = new List<int>(); for (int i = 0; i < colMeshes.Count; i++) order.Add(i);
        order.Sort((a, b) => colMeshes[a].bounds.SqrDistance(p).CompareTo(colMeshes[b].bounds.SqrDistance(p)));
        var m2 = new List<Mesh>(); var o2 = new List<GameObject>();
        foreach (int i in order) { m2.Add(colMeshes[i]); o2.Add(colObjs[i]); }
        colMeshes.Clear(); colMeshes.AddRange(m2); colObjs.Clear(); colObjs.AddRange(o2);
        while (colMeshes.Count > 0 && colMeshes[0].bounds.SqrDistance(p) < 200f * 200f) BakeNext();
    }

    void BakeNext()
    {
        var m = colMeshes[0]; var go = colObjs[0]; colMeshes.RemoveAt(0); colObjs.RemoveAt(0);
        if (go) go.AddComponent<MeshCollider>().sharedMesh = m;
    }

    static float F(byte[] b, ref int o) { float v = BitConverter.ToSingle(b, o); o += 4; return v; }
    static int I(byte[] b, ref int o) { int v = BitConverter.ToInt32(b, o); o += 4; return v; }

    /// LMW1: compact web format written by Tools/pack_web.py
    void LoadWeb(byte[] b)
    {
        int o = 0;
        if (b[0] != 'L' || b[1] != 'M' || b[2] != 'W' || b[3] != '1') throw new Exception("bad web magic");
        o = 4;
        var map = MatMap();
        int nm = I(b, ref o); var mats = new Material[nm];
        for (int i = 0; i < nm; i++)
        {
            int l = I(b, ref o); string n = System.Text.Encoding.UTF8.GetString(b, o, l); o += l;
            mats[i] = map.TryGetValue(n, out var m) && m ? m : fallback;
            if (n == "Water") waterMaterial = mats[i];
        }
        bool mobile = Application.isMobilePlatform;
        int nc = I(b, ref o);
        for (int c = 0; c < nc; c++)
        {
            int l = I(b, ref o); string name = System.Text.Encoding.UTF8.GetString(b, o, l); o += l;
            int nv = I(b, ref o);
            float mx = F(b, ref o), my = F(b, ref o), mz = F(b, ref o);
            float rx = F(b, ref o), ry = F(b, ref o), rz = F(b, ref o);
            float ru = F(b, ref o), rv = F(b, ref o);
            int uvf32 = I(b, ref o);
            var pos = new Vector3[nv]; var nrm = new Vector3[nv]; var uv = new Vector2[nv];
            const float q = 1f / 65535f;
            for (int i = 0; i < nv; i++)
            {
                int k = o + i * 6;
                pos[i] = new Vector3(mx + (b[k] | b[k + 1] << 8) * q * rx, my + (b[k + 2] | b[k + 3] << 8) * q * ry, mz + (b[k + 4] | b[k + 5] << 8) * q * rz);
            }
            o += nv * 6;
            for (int i = 0; i < nv; i++)
            {
                float ex = (sbyte)b[o + i * 2] / 127f, ez = (sbyte)b[o + i * 2 + 1] / 127f;
                float ey = 1f - Mathf.Abs(ex) - Mathf.Abs(ez);
                if (ey < 0) { float tx = ex; ex = (1f - Mathf.Abs(ez)) * (tx >= 0 ? 1 : -1); ez = (1f - Mathf.Abs(tx)) * (ez >= 0 ? 1 : -1); }
                nrm[i] = new Vector3(ex, ey, ez).normalized;
            }
            o += nv * 2;
            if (uvf32 != 0) { for (int i = 0; i < nv; i++) { uv[i] = new Vector2(BitConverter.ToSingle(b, o + i * 8), BitConverter.ToSingle(b, o + i * 8 + 4)); } o += nv * 8; }
            else { for (int i = 0; i < nv; i++) { int k = o + i * 4; uv[i] = new Vector2((b[k] | b[k + 1] << 8) * q * ru, (b[k + 2] | b[k + 3] << 8) * q * rv); } o += nv * 4; }
            int ns = I(b, ref o);
            var mesh = new Mesh { name = name, indexFormat = nv > 65535 ? IndexFormat.UInt32 : IndexFormat.UInt16 };
            mesh.SetVertices(pos); mesh.SetNormals(nrm); mesh.SetUVs(0, uv);
            mesh.subMeshCount = ns;
            var rm = new Material[ns];
            for (int s = 0; s < ns; s++)
            {
                int mid = I(b, ref o); int ni = I(b, ref o); int bits = I(b, ref o);
                var idx = new int[ni];
                if (bits == 16) { for (int i = 0; i < ni; i++) idx[i] = b[o + i * 2] | b[o + i * 2 + 1] << 8; o += ni * 2; if ((ni * 2) % 4 != 0) o += 2; }
                else { for (int i = 0; i < ni; i++) idx[i] = BitConverter.ToInt32(b, o + i * 4); o += ni * 4; }
                mesh.SetTriangles(idx, s, false);
                rm[s] = mats[mid];
                Triangles += ni / 3;
            }
            string layer = name.Substring(0, name.IndexOf('_'));
            bool tang = layer == "bld" || layer == "road" || layer == "bar" || layer == "water";
            AddChunk(name, mesh, rm, tang && !mobile || layer == "water");
        }
    }

    void Update()
    {
        if (colMeshes.Count > 0)
        {
            float t0 = Time.realtimeSinceStartup;
            while (colMeshes.Count > 0 && Time.realtimeSinceStartup - t0 < 0.006f) BakeNext();
        }
        if (waterMaterial)
        {
            float t = Time.time;
            waterMaterial.SetTextureOffset("_BumpMap", new Vector2(t * 0.012f, t * 0.006f));
        }
    }
}
